let recording=null;let lastReport=null;
export function startBenchmark(){recording={started:performance.now(),frames:[],last:0};window.dispatchEvent(new Event('brasa:benchmark-start'));return recording}
export function recordFrame(timestamp){if(!recording)return;const r=recording;if(r.last)r.frames.push(timestamp-r.last);r.last=timestamp;if(timestamp-r.started<20000)return;const frames=r.frames.filter(n=>n>0&&n<1000).sort((a,b)=>a-b);const total=frames.reduce((a,b)=>a+b,0);lastReport={version:1,measuredAt:new Date().toISOString(),durationMs:Math.round(timestamp-r.started),frames:frames.length,averageFps:frames.length?Math.round(frames.length*1000/total):0,p95FrameMs:frames.length?Math.round(frames[Math.floor(frames.length*.95)]*10)/10:null,viewport:{width:innerWidth,height:innerHeight,dpr:devicePixelRatio},platform:navigator.userAgent,method:'Tempos de requestAnimationFrame durante 20 segundos neste navegador. Não é certificação de aparelho físico.',memoryBytes:performance.memory?.usedJSHeapSize??null};recording=null;window.dispatchEvent(new CustomEvent('brasa:benchmark-result',{detail:lastReport}));}
export function downloadBenchmark(){if(!lastReport)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(lastReport,null,2)],{type:'application/json'}));a.download='brasa-desempenho.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
